div.script:
const header = document.querySelector("header");
const body = document.querySelector("body");
const mnb = document.getElementById("mobile-nav-btn"),
  mn = document.getElementById("mobile-nav"),
  headerNav = document.getElementById("header-nav");
function getWindowWidth() {
    return window.innerWidth;
}
function changescroll() {
  body.classList.add((headerNav.dataset.nav === 'open') ? "overflow-hidden" : "overflow-y-auto");
}
!!mnb && (mnb.onclick = () => {
  !!mn && (mn.style.top = `${Math.floor(header.offsetHeight + header.offsetTop - document.body.scrollTop)}px`);
  if(headerNav) {
    headerNav.dataset.nav = (headerNav.dataset.nav === 'open')?'close':'open';
  }
  changescroll();
});
window.addEventListener("resize",
  function (event) {
    var windowSize = getWindowWidth();
    if (windowSize > 1024) {
      body.classList.add("overflow-y-auto");
    }else{
      if(headerNav && headerNav.dataset.nav === 'open') {
        body.classList.add("overflow-hidden");
        mn.style.top = `${Math.floor(header.offsetHeight + header.offsetTop - document.body.scrollTop)}px`
      }
    }
  }
);
